er handlande verksamhet. Vårt fokus på både lokal förankring och global räckvidd säkerställer långsiktig stabilitet och affärsnytta.'::text), true), '{fsc,keyPoints}', jsonb_build_array('Fokus på tillverkande och handlande bolag.', 'Lokal närvaro med global leveransförmåga.', 'Strukturerad implementation och förvaltning.', 'End-to-end-ansvar för hela livscykeln.'), true) WHERE id = 'e97862ae-7d14-44da-9ea3-7e2de1140a10'; UPDATE partners SET product_filters = jsonb_set(jsonb_set(product_filters, '{bc,whyChoose}', to_jsonb('Vi erbjuder Business Central som en helhetslösning med fokus på tillverkning, bygg & entreprenad, samt energi & utilities, för att möta era specifika branschbehov.'::text), true), '{bc,keyPoints}', jsonb_build_array('Branschspecifik anpassning för Business Central.', 'Implementering och rådgivning för Business Central.', 'Stöder integration med Finance och SCM.', 'Fem kontor i Sverige för nära support.'), true) WHERE id = 'f1947f70-3320-43b0-af09-8387d7546fa3'; UPDATE partners SET product_filters = jsonb_set(jsonb_set(product_filters, '{fsc,whyChoose}', to_jsonb('Vi optimerar er tillverknings- eller energiverksamhets logistik- och leveransflöden. Våra D365 F&SCM-lösningar är anpassade för er specifika bransch och garanterar verksamhetsnytta.'::text), true), '{fsc,keyPoints}', jsonb_build_array('D365 F&SCM för tillverkning & energi.', 'Bred geografisk närvaro i Sverige.', 'Anpassar lösningar för er affärsnytta.', 'Optimerar ekonomi, logistik och underhåll.'), true) WHERE id = 'f1947f70-3320-43b0-af09-8387d7546fa3'; UPDATE partners SET product_filters = jsonb_set(jsonb_set(product_filters, '{bc,whyChoose}', to_jsonb('Vi erbjuder Business Central-implementeringar som anpassar sig till era specifika affärsprocesser, vare sig ni är grossist-, retail- eller tjänstebolag. Vårt fokus är att effektivisera er verksamhet, nationellt och internationellt.'::text), true), '{bc,keyPoints}', jsonb_build_array('Anpassar Business Central för grossist, retail och tjänster.', 'Stöder internationella verksamheter effektivt.', 'Integrerar med andra Dynamics 365-applikationer.', 'Hanterar hela projektets livscykel, från analys till support.'), true) WHERE id = '42f8b63b-a4c9-480d-81e5-a322652b3af4'; UPDATE partners SET product_filters = jsonb_set(jsonb_set(product_filters, '{fsc,whyChoose}', to_jsonb('Vi hjälper er att optimera global logistik och leveranskedja med datadriven verksamhetsstyrning. Våra lösningar skapar mätbar affärsnytta för er organisation.'::text), true), '{fsc,keyPoints}', jsonb_build_array('Expertis inom tillverkning, grossist och life science.', 'Optimerar global logistik och leveranskedja.', 'Integrerar data och processer i ett system.', 'Brett erbjudande från ekonomi till lagerhantering.'), true) WHERE id = '42f8b63b-a4c9-480d-81e5-a322652b3af4'; UPDATE partners SET product_filters = jsonb_set(jsonb_set(product_filters, '{sales,whyChoose}', to_jsonb('Vi hjälper er att omsätta era kunddata till handlingskraftiga insikter. Vi kan leverera meningsfulla kundupplevelser med AI-driven kunddata, särskilt inom fastighet, tillverkning och konsulttjänster.'::text), true), '{sales,keyPoints}', jsonb_build_array('Vi kombinerar affärssystem, kunddata, AI och automatisering.', 'Vi erbjuder förbättrade kundupplevelser längs hela kundresan.', 'Vi har specifik branschkunskap inom fastighet, tillverkning, IT-konsult.', 'Vi använder den fulla bredden av Microsoftplattformen.'), true) WHERE id = '42f8b63b-a4c9-480d-81e5-a322652b3af4';